// DISTROPLUS ERP: OFFICIAL GOOGLE DRIVE AUTO-BACKUP WEBHOOK SCRIPT
// Paste this in https://script.google.com and deploy as Web App
// ====================================================================

function doPost(e) {
  try {
    var data = JSON.parse(e.postData.contents);
    
    // 1. Resolve Target Folder (Supports Name, Drive URL, or Folder ID)
    var folderInput = String(data.folderName || data.folderId || "DistroPlus Invoices & Bills").trim();
    var folder = null;
    
    // Check if user provided a full Google Drive URL or direct Folder ID
    var candidateId = null;
    if (folderInput.indexOf("folders/") !== -1) {
      candidateId = folderInput.split("folders/")[1].split("/")[0].split("?")[0].trim();
    } else if (folderInput.length >= 25 && folderInput.indexOf(" ") === -1 && folderInput.indexOf("http") === -1) {
      candidateId = folderInput.trim();
    }
    
    if (candidateId) {
      try {
        folder = DriveApp.getFolderById(candidateId);
      } catch (fErr) {
        // Fallback to name search if ID not accessible
      }
    }
    
    if (!folder) {
      var folderName = folderInput;
      if (folderName.indexOf("http") === 0) {
        folderName = "DistroPlus Invoices & Bills";
      }
      var folders = DriveApp.getFoldersByName(folderName);
      folder = folders.hasNext() ? folders.next() : DriveApp.createFolder(folderName);
    }
    
    // 2. Handle DELETE_BILL Action (User confirmed deletion from Drive)
    if (data.action === "DELETE_BILL" || data.action === "delete") {
      var invNo = String(data.invoiceNo || "").replace(/[^a-zA-Z0-9]/g, "_");
      var trashedCount = 0;
      
      // A. If driveFileId passed directly, trash it immediately
      if (data.driveFileId) {
        try {
          var targetFile = DriveApp.getFileById(data.driveFileId);
          if (targetFile) {
            targetFile.setTrashed(true);
            trashedCount++;
          }
        } catch(fErr) {}
      }
      
      // B. Also search inside folder for matching invoice files (by invoice number)
      if (folder && invNo) {
        var files = folder.getFiles();
        while (files.hasNext()) {
          var f = files.next();
          var fn = f.getName();
          if (fn.indexOf(invNo) !== -1) {
            f.setTrashed(true);
            trashedCount++;
          }
        }
      }
      
      return ContentService.createTextOutput(JSON.stringify({
        success: true,
        action: "DELETED",
        trashedCount: trashedCount,
        invoiceNo: data.invoiceNo,
        timestamp: new Date().toISOString()
      })).setMimeType(ContentService.MimeType.JSON);
    }

    // 3. Clean File Name for Upload
    var invNo = String(data.invoiceNo || "Invoice").replace(/[^a-zA-Z0-9]/g, "_");
    var custName = String(data.customerName || "Customer").replace(/[^a-zA-Z0-9]/g, "_");
    var fileName = "Bill_" + invNo + "_" + custName;
    
    // 3. Convert HTML to High-Res Vector PDF natively in Google Drive!
    var htmlContent = data.html || ("<h1>Tax Invoice #" + invNo + "</h1>");
    var htmlBlob = Utilities.newBlob(htmlContent, 'text/html', fileName + '.html');
    var pdfBlob = htmlBlob.getAs('application/pdf').setName(fileName + '.pdf');
    
    // 4. Update existing bill file or create fresh (Avoids duplicate files)
    var existingFiles = folder.getFilesByName(fileName + '.pdf');
    while (existingFiles.hasNext()) {
      existingFiles.next().setTrashed(true);
    }
    
    var file = folder.createFile(pdfBlob);
    try {
      file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);
    } catch (shareErr) {}
    
    return ContentService.createTextOutput(JSON.stringify({
      success: true,
      fileId: file.getId(),
      fileUrl: file.getUrl(),
      fileName: file.getName(),
      folderUrl: folder.getUrl(),
      folderName: folder.getName(),
      timestamp: new Date().toISOString()
    })).setMimeType(ContentService.MimeType.JSON);
    
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({
      success: false,
      error: err.toString()
    })).setMimeType(ContentService.MimeType.JSON);
  }
}

function doGet(e) {
  return ContentService.createTextOutput(JSON.stringify({
    status: "active",
    service: "DistroPlus Google Drive Auto-Backup Webhook",
    timestamp: new Date().toISOString()
  })).setMimeType(ContentService.MimeType.JSON);
}

function testWebhook() {
  Logger.log("DistroPlus Webhook Script is active and working properly!");
}
